/**
 * Chart Studio specs: 100 interactive charts that run on the native chart widgets. Each spec
 * names its host (Bar Chart, Pie Chart or Line Graph), so its data is edited in that widget's own
 * data panel and variables; options.motion = spec id switches the widget to this chart's renderer
 * (renderers.ts) and runtime (kit.ts: entrance springs, hover, selection, scrubbing and drags).
 *
 * Data is normalised to { labels, series[] } whatever the host (pie slices become one series).
 */
export type ChartHost = 'bar' | 'pie' | 'line';
export interface ChartSeries {
    name: string;
    values: number[];
    color?: string;
}
export interface ChartData {
    labels: string[];
    series: ChartSeries[];
}
export interface ChartSpec {
    id: string;
    num: number;
    cat: number;
    name: string;
    desc: string;
    tags: string[];
    host: ChartHost;
    W: number;
    H: number;
    data: ChartData;
    title: string;
    /** extra knobs beyond speed / stagger / bounce */
    knobs?: string[];
    /** keeps moving after the entrance (particles, waves, live feeds) */
    live?: boolean;
    /** what pressing and dragging does (shown in the panel) */
    drag?: string;
    /** cycles through these modes (state machine Number input `mode`) */
    modes?: string[];
    /** hides the card title (charts that fill their card) */
    bare?: boolean;
}
export declare const CHART_CATEGORIES: {
    id: number;
    name: string;
    blurb: string;
}[];
export declare const MONTHS: string[];
export declare function rnd(seed: number): () => number;
export declare const CHART_SPECS: ChartSpec[];
export declare function chartSpecById(id: string | undefined): ChartSpec | undefined;
